var userTranslations=Object.create(null);try{const cached=JSON.parse(localStorage.getItem('h3-translations-v1')||'{}');for(const [k,v]of Object.entries(cached))if(typeof v==='string')userTranslations[k]=v;const draft=JSON.parse(localStorage.getItem('h3-draft-v1')||'null');if(draft?.translations)for(const [k,v]of Object.entries(draft.translations))if(typeof v==='string')userTranslations[k]=v}catch{}
function translationOf(en){return userTranslations[en]??translateKnown(en)??''}
function bilingualSegments(){let s=state(),items=[];items.push({label:'設定',en:`${s.mode} / ${s.duration} seconds / ${s.ratio}`,ja:`${s.mode} / ${s.duration}秒 / ${s.ratio}`,fixed:true});if(s.mode==='I2VA')items.push({label:'先頭画像',en:'Picture 1 is fully referenced at 0.00 seconds in Shot 1.',ja:'Picture 1を0.00秒のShot 1の先頭フレームとして使用する。',fixed:true});if(s.mode==='FL2VA')items.push({label:'先頭・末尾画像',en:`Picture 1 aligns with 0.00 seconds; Picture 2 aligns with ${Number(s.duration).toFixed(2)} seconds in Shot ${s.shots.length}.`,ja:`Picture 1を0.00秒の先頭、Picture 2を${Number(s.duration).toFixed(2)}秒の最終ショット（Shot ${s.shots.length}）の末尾として使用する。`,fixed:true});if(s.mode==='L2VA')items.push({label:'末尾画像',en:`Picture 1 aligns with ${Number(s.duration).toFixed(2)} seconds in Shot ${s.shots.length}.`,ja:`Picture 1を${Number(s.duration).toFixed(2)}秒の最終ショット（Shot ${s.shots.length}）の末尾として使用する。`,fixed:true});if(s.mode==='Ref2VA')for(let [key,label]of [['definitions','参照素材の定義'],['summary','要約'],['retention','保持関係']])items.push({label,en:s[key],ja:translationOf(s[key])});items.push({label:'映像の見た目・照明',en:s.style,ja:translationOf(s.style)});s.shots.forEach((x,i)=>{items.push({label:`Shot ${i+1}${i?' / '+x.time+'秒でカット':''}`,en:x.description,ja:translationOf(x.description)});if(x.dialogue){items.push({label:`Shot ${i+1} / 話者`,en:x.speaker,ja:translationOf(x.speaker)});items.push({label:`Shot ${i+1} / セリフ (${x.language})`,en:x.dialogue,ja:x.dialogue,fixed:true});if(x.voiceover)items.push({label:'ナレーション',en:'Off-screen voiceover; the on-screen character keeps their lips completely closed.',ja:'画面外のナレーション。画面内の人物は唇を完全に閉じたまま。',fixed:true})}});for(let [label,en]of [['環境音・動作音',s.silent?'N/A':s.sound],['観客向けBGM',s.silent||s.noMusic?'N/A':s.music]])items.push({label,en,ja:translationOf(en)});return items}
function bilingualText(){return 'H3完成プロンプト（英語）\n\n'+$('output').value+'\n\n日本語確認訳\n\n'+bilingualSegments().map(x=>x.label+'\n'+x.en+'\n'+(x.ja||'［日本語訳未入力］')).join('\n\n')}
function syncBilingual(){if(!$('bilingualDialog').open)return;const box=$('bilingualRows');box.replaceChildren();for(const item of bilingualSegments()){let section=document.createElement('section');section.className='translation-row';let title=document.createElement('h3');title.textContent=item.label;let grid=document.createElement('div');grid.className='translation-grid';let en=document.createElement('div');let enTag=document.createElement('strong');enTag.textContent='ENGLISH';let enText=document.createElement('p');enText.textContent=item.en||'（未入力）';en.append(enTag,enText);let ja=document.createElement('label');ja.textContent='日本語';let area=document.createElement('textarea');area.value=item.ja;area.placeholder='日本語訳未入力 — 下の翻訳依頼ボタンでAIへ依頼し、訳をここに入力できます。';area.readOnly=!!item.fixed;area.oninput=()=>{userTranslations[item.en]=area.value;try{localStorage.setItem('h3-translations-v1',JSON.stringify(userTranslations))}catch{} };ja.append(area);grid.append(en,ja);section.append(title,grid);box.append(section)}let full=document.createElement('details');full.innerHTML='<summary>コピー用の完成英語プロンプト</summary>';let out=document.createElement('textarea');out.readOnly=true;out.value=$('output').value;full.append(out);box.append(full)}
$('bilingual').onclick=()=>{$('bilingualDialog').showModal();syncBilingual()};$('closeBilingual').onclick=()=>$('bilingualDialog').close();$('downloadBilingual').onclick=()=>download('h3-prompt-en-ja.txt',bilingualText(),'text/plain;charset=utf-8');
$('translationRequest').onclick=async()=>{let missing=bilingualSegments().filter(x=>!x.ja&&x.en.trim());let request='以下のMiniMax H3プロンプトの各英文を日本語に訳してください。番号・参照ラベル・秒数・セリフの原文を保持し、映像の動きとカメラの違いを正確に訳してください。英語と日本語を対にして出力してください。\n\n'+(missing.length?missing:bilingualSegments().filter(x=>!x.fixed)).map(x=>x.label+'\n'+x.en).join('\n\n');try{await navigator.clipboard.writeText(request);$('bilingualStatus').textContent='翻訳依頼をコピーしました。AIへ貼り付けて、訳を日本語欄へ入力してください。'}catch{let area=document.createElement('textarea');area.value=request;$('bilingualRows').prepend(area);area.focus();area.select();$('bilingualStatus').textContent='コピーできませんでした。選択された依頼文を手動でコピーしてください。'}};
$('newWindow').onclick=()=>{let w=window.open('','_blank');if(!w){$('bilingualStatus').textContent='別ウインドウがブロックされました。この画面で日英を確認できます。';return}w.document.write('<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>H3 / 英語＋日本語</title><style>body{font-family:system-ui;background:#0b1020;color:#edf3ff;max-width:1200px;margin:auto;padding:24px}section{border-bottom:1px solid #43516e;padding:15px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}p,pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8}h3{color:#b8fa73}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style><h1>H3 / 英語＋日本語</h1><p>開いた時点の内容です。修正後は元の画面から開き直してください。</p><main></main></html>');w.document.close();let main=w.document.querySelector('main');for(const x of bilingualSegments()){let section=w.document.createElement('section');let h=w.document.createElement('h3');h.textContent=x.label;let g=w.document.createElement('div');g.className='grid';for(const text of ['ENGLISH\n'+x.en,'日本語\n'+(x.ja||'［日本語訳未入力］')]){let p=w.document.createElement('p');p.textContent=text;g.append(p)}section.append(h,g);main.append(section)}let pre=w.document.createElement('pre');pre.textContent='完成英語プロンプト\n\n'+$('output').value;main.append(pre);w.opener=null};
